CREATE OR REPLACE FUNCTION public.team_orders() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public
AS $function$ DECLARE access text:=public.team_access(); result jsonb; BEGIN IF access IS NULL THEN RAISE EXCEPTION 'Prieiga negalima'; END IF; EXECUTE 'SELECT coalesce(jsonb_agg(CASE WHEN $1=''super_admin'' THEN to_jsonb(o) ELSE to_jsonb(o)-''price''-''discount_amount''-''original_price''-''promo_code''-''promo_code_id''-''discount_label''-''promo_note'' END ORDER BY o.created_at DESC),''[]''::jsonb) FROM public.orders o' INTO result USING access; RETURN result; END $function$;